<script>
document.addEventListener('DOMContentLoaded',()=>{
const rows=@json($departments);const names=[...new Set(rows.map(x=>x.department||'Unassigned'))];
const counts=(g)=>names.map(n=>rows.filter(x=>(x.department||'Unassigned')===n && String(x.gender||'').toLowerCase()===g).reduce((a,x)=>a+Number(x.total),0));
new Chart(document.getElementById('departmentChart'),{type:'bar',data:{labels:names,datasets:[{label:'Male',data:counts('male'),backgroundColor:'#9ab2d5'},{label:'Female',data:counts('female'),backgroundColor:'#2472b2'}]},options:{responsive:true,scales:{x:{stacked:true},y:{stacked:true,beginAtZero:true}}}});
new Chart(document.getElementById('genderChart'),{type:'pie',data:{labels:['Male','Female','Other / Unspecified'],datasets:[{data:[@json($male),@json($female),@json(max(0,$total-$male-$female))],backgroundColor:['#2275b5','#ff7c20','#a8b1bf']}]},options:{responsive:true}});
});</script>
